-- Specific, context-based practice prompts for the Indonesia-focused course catalog.
-- Idempotent update: each prompt is replaced with the reviewed prompt for its lesson.
update public.lessons as l
set content=jsonb_set(l.content,'{exercise}',v.exercise,true)
from (values
('d3000000-0000-4000-8000-000000000001'::uuid,'Isi tabel pemicu tekanan, tanda yang Anda rasakan, hal yang dapat dikendalikan, dan satu orang dewasa tepercaya untuk dihubungi. Pilih satu strategi aman untuk dicoba minggu ini.'::jsonb),
('d3000000-0000-4000-8000-000000000002'::uuid,'Tentukan satu target proses selama tujuh hari (misalnya 25 menit belajar pada jam yang sama). Catat pelaksanaan, hambatan, dan cara kembali ke rutinitas tanpa menyalahkan diri.'::jsonb),
('d3000000-0000-4000-8000-000000000003'::uuid,'Buat jadwal belajar 14 hari untuk dua mata pelajaran prioritas. Gunakan sesi singkat, latihan dari ingatan, jeda, tidur cukup, dan satu sesi tinjauan mingguan.'::jsonb),
('d3000000-0000-4000-8000-000000000004'::uuid,'Ambil lima kesalahan dari latihan soal. Kelompokkan sebagai konsep, ketelitian, strategi, atau waktu; pilih latihan yang sesuai untuk setiap penyebab.'::jsonb),
('d3000000-0000-4000-8000-000000000005'::uuid,'Temukan portal resmi SPMB daerah Anda. Catat URL, tahun ajaran, jadwal, jalur yang tersedia, dokumen, dan tanggal pengecekan; tandai hal yang belum jelas untuk ditanyakan ke sekolah/dinas.'::jsonb),
('d3000000-0000-4000-8000-000000000006'::uuid,'Bandingkan tiga pilihan sekolah berdasarkan minat, aturan resmi, akses, biaya, dukungan, dan pilihan cadangan. Jelaskan langkah berikutnya untuk setiap opsi tanpa menganggap satu sekolah menentukan masa depan.'::jsonb),
('d3000000-0000-4000-8000-000000000007'::uuid,'Pilih satu kebiasaan kecil. Catat pemicu, waktu, cara menyiapkan alat, dan cek harian selama tujuh hari; evaluasi pola, bukan nilai diri.'::jsonb),
('d3000000-0000-4000-8000-000000000008'::uuid,'Lakukan satu sesi fokus 20 menit pada tugas nyata. Catat gangguan yang muncul dan ubah satu pengaturan gawai atau ruang belajar.'::jsonb),
('d3000000-0000-4000-8000-000000000009'::uuid,'Untuk skenario terlambat menyelesaikan tugas kelompok, tulis pengakuan yang jujur, dampak, tindakan perbaikan, dan cara mencegah pengulangan.'::jsonb),
('d3000000-0000-4000-8000-000000000010'::uuid,'Untuk contoh perundungan daring, susun langkah aman: jangan memperbesar konflik, simpan bukti seperlunya, dukung teman, blokir/laporkan jika sesuai, dan hubungi orang dewasa tepercaya.'::jsonb),
('d3000000-0000-4000-8000-000000000011'::uuid,'Minta umpan balik pada satu tugas, pilih dua saran yang spesifik, revisi hasil, lalu jelaskan apa yang berubah dan mengapa.'::jsonb),
('d3000000-0000-4000-8000-000000000012'::uuid,'Tulis permintaan bantuan dengan format: yang sudah dicoba, bagian yang sulit, bukti atau contoh, dan bantuan spesifik yang Anda butuhkan.'::jsonb),
('d3000000-0000-4000-8000-000000000013'::uuid,'Daftar lima keterampilan dari sekolah, PKL, organisasi, proyek atau membantu usaha keluarga. Untuk tiap keterampilan, beri contoh tindakan dan hasil yang benar-benar terjadi.'::jsonb),
('d3000000-0000-4000-8000-000000000014'::uuid,'Audit dua lowongan simulasi. Tandai identitas perusahaan, uraian kerja, alamat resmi, syarat, biaya yang diminta, dan data pribadi; tulis apa yang perlu diverifikasi sebelum melamar.'::jsonb),
('d3000000-0000-4000-8000-000000000015'::uuid,'Buat CV satu halaman untuk posisi pemula. Sesuaikan tiga butir pengalaman dengan kebutuhan pekerjaan dan jangan mencantumkan klaim atau sertifikat yang tidak dimiliki.'::jsonb),
('d3000000-0000-4000-8000-000000000016'::uuid,'Jawab tiga pertanyaan wawancara dengan pola situasi-tindakan-hasil. Gunakan contoh nyata, jelaskan apa yang dipelajari, dan hindari membocorkan data rahasia pihak lain.'::jsonb),
('d3000000-0000-4000-8000-000000000017'::uuid,'Tulis pesan profesional kepada atasan tentang keterlambatan tugas: kondisi, dampak, rencana pemulihan, dan waktu pembaruan. Gunakan bahasa yang jelas dan bertanggung jawab.'::jsonb),
('d3000000-0000-4000-8000-000000000018'::uuid,'Buat daftar pertanyaan sebelum menerima pekerjaan tentang tugas, status hubungan kerja, upah, jadwal, lembur, keselamatan, kontrak, dan kanal konsultasi resmi. Tandai hal yang harus diverifikasi.'::jsonb),
('d3000000-0000-4000-8000-000000000019'::uuid,'Buat matriks jalur kuliah, vokasi/pelatihan, kerja, magang, dan usaha. Untuk setiap jalur, tulis syarat, kecocokan, biaya, dukungan, dan hal yang belum diketahui.'::jsonb),
('d3000000-0000-4000-8000-000000000020'::uuid,'Bandingkan biaya dua pilihan menggunakan angka yang dapat diperiksa: biaya belajar, transportasi, perangkat, waktu, dan bantuan yang tersedia. Pisahkan fakta dari perkiraan.'::jsonb),
('d3000000-0000-4000-8000-000000000021'::uuid,'Siapkan lima pertanyaan untuk alumni, pekerja, lembaga pelatihan, atau pelaku usaha tentang tugas sehari-hari, syarat masuk, risiko, dan perkembangan; catat sumber dan tanggal.'::jsonb),
('d3000000-0000-4000-8000-000000000022'::uuid,'Selesaikan proyek mini yang mewakili satu jalur pilihan, seperti desain poster, analisis data sederhana, halaman web, layanan komunitas, atau rencana usaha. Minta umpan balik satu orang.'::jsonb),
('d3000000-0000-4000-8000-000000000023'::uuid,'Buat rencana 30-60-90 hari dengan satu tindakan dalam 48 jam, indikator kemajuan, biaya, orang pendukung, dan jadwal tinjauan.'::jsonb),
('d3000000-0000-4000-8000-000000000024'::uuid,'Daftar tiga risiko rencana utama, tanda awal, mitigasi, dan alternatif. Tentukan kapan Anda akan meninjau ulang pilihan berdasarkan bukti baru.'::jsonb),
('d3000000-0000-4000-8000-000000000025'::uuid,'Wawancarai lima calon pelanggan tentang kebutuhan dan pengalaman mereka. Catat kata-kata mereka, pola yang berulang, dan siapa yang belum terwakili; jangan langsung memaksa menjual.'::jsonb),
('d3000000-0000-4000-8000-000000000026'::uuid,'Rancang uji penawaran tujuh hari dengan anggaran kecil dan batas kerugian yang bisa diterima. Tentukan metrik belajar dan kondisi untuk lanjut, ubah, atau berhenti.'::jsonb),
('d3000000-0000-4000-8000-000000000027'::uuid,'Hitung HPP satu produk/jasa: bahan, kemasan, transportasi, biaya platform, waktu kerja, dan biaya tetap. Uji dampak kenaikan biaya bahan 10% terhadap margin.'::jsonb),
('d3000000-0000-4000-8000-000000000028'::uuid,'Buat catatan kas 14 hari dengan saldo awal, pemasukan, pengeluaran, utang pelanggan, dan saldo akhir. Pisahkan uang pribadi dan usaha lalu rekonsiliasi.'::jsonb),
('d3000000-0000-4000-8000-000000000029'::uuid,'Buat penawaran produk untuk pelanggan lokal: kebutuhan, manfaat, harga, ketersediaan, batas layanan, cara pesan, dan foto yang representatif. Hindari klaim berlebihan.'::jsonb),
('d3000000-0000-4000-8000-000000000030'::uuid,'Simulasikan komplain karena pesanan terlambat atau kualitas tidak sesuai. Tulis respons, solusi yang berada dalam kewenangan, pencatatan, dan langkah mencegah kejadian berulang.'::jsonb),
('d3000000-0000-4000-8000-000000000031'::uuid,'Buat struktur folder proyek dengan aturan nama file, versi, dan cadangan. Uji apakah anggota tim dapat menemukan dokumen tanpa akses berlebihan.'::jsonb),
('d3000000-0000-4000-8000-000000000032'::uuid,'Buat dokumen satu halaman dan lima slide untuk menjelaskan masalah lokal. Periksa struktur heading, kontras, sumber, dan keterbacaan di layar ponsel.'::jsonb),
('d3000000-0000-4000-8000-000000000033'::uuid,'Susun spreadsheet anggaran atau inventaris dengan SUM, AVERAGE, filter, dan validasi angka. Cocokkan satu total dengan perhitungan manual.'::jsonb),
('d3000000-0000-4000-8000-000000000034'::uuid,'Buat ruang kerja tim simulasi dengan izin lihat/edit sesuai peran. Jelaskan bagaimana menghapus akses yang tidak lagi dibutuhkan.'::jsonb),
('d3000000-0000-4000-8000-000000000035'::uuid,'Gunakan AI untuk membuat draf tugas; simpan prompt awal, prompt revisi, kriteria kualitas, dan bagian yang Anda ubah. Jangan masukkan data pribadi atau rahasia.'::jsonb),
('d3000000-0000-4000-8000-000000000036'::uuid,'Audit lima klaim dalam jawaban AI. Untuk tiap klaim, cari sumber asli yang relevan, tandai dukungan/kontradiksi/tidak terverifikasi, dan jelaskan ketidakpastian.'::jsonb),
('d3000000-0000-4000-8000-000000000037'::uuid,'Buat halaman profil proyek dengan HTML semantik, heading berurutan, tautan yang jelas, dan teks alternatif untuk gambar.'::jsonb),
('d3000000-0000-4000-8000-000000000038'::uuid,'Uji halaman pada lebar ponsel dan desktop. Perbaiki tiga masalah layout, kontras, fokus keyboard, atau ukuran teks; catat sebelum/sesudah.'::jsonb),
('d3000000-0000-4000-8000-000000000039'::uuid,'Buat kalkulator anggaran atau daftar tugas sederhana dengan JavaScript. Uji input normal, kosong, dan nilai batas; jelaskan apa yang belum ditangani.'::jsonb),
('d3000000-0000-4000-8000-000000000040'::uuid,'Dokumentasikan satu bug dengan langkah reproduksi, pesan error, dugaan penyebab, perubahan kode, dan hasil pengujian setelah perbaikan.'::jsonb),
('d3000000-0000-4000-8000-000000000041'::uuid,'Tulis README yang berisi tujuan, fitur, cara mencoba, tangkapan layar buatan sendiri, keterbatasan, dan sumber/lisensi aset.'::jsonb),
('d3000000-0000-4000-8000-000000000042'::uuid,'Uji prototipe dengan dua pengguna sukarela. Catat tugas yang mereka coba, kebingungan yang muncul, umpan balik, dan satu iterasi perbaikan.'::jsonb),
('d3000000-0000-4000-8000-000000000043'::uuid,'Buat profil satu segmen pelanggan dari tiga wawancara singkat. Tulis kebutuhan, kendala, cara membeli, dan batasan sampel; jangan menebak berdasarkan stereotip.'::jsonb),
('d3000000-0000-4000-8000-000000000044'::uuid,'Buat katalog tiga produk dengan foto representatif, harga, ukuran, ketersediaan, wilayah layanan, dan aturan pemesanan yang jelas.'::jsonb),
('d3000000-0000-4000-8000-000000000045'::uuid,'Susun kalender konten tujuh hari. Untuk tiap konten tulis tujuan, audiens, format, ajakan, dan ukuran keberhasilan yang realistis.'::jsonb),
('d3000000-0000-4000-8000-000000000046'::uuid,'Buat satu posting produk dengan foto sendiri atau aset berizin, teks yang akurat, alt text, dan izin jika menampilkan orang atau testimoni.'::jsonb),
('d3000000-0000-4000-8000-000000000047'::uuid,'Simulasikan pesanan dan komplain lewat chat. Tulis jawaban sopan, konfirmasi transaksi melalui aplikasi resmi, dan tandai data pribadi yang tidak perlu dikumpulkan.'::jsonb),
('d3000000-0000-4000-8000-000000000048'::uuid,'Gunakan data contoh untuk membandingkan dua konten berdasarkan jangkauan, pertanyaan, konversi, dan biaya. Jelaskan keterbatasan data sebelum menyimpulkan.'::jsonb),
('d3000000-0000-4000-8000-000000000049'::uuid,'Buat anggaran dari pemasukan simulasi. Pisahkan kebutuhan, kewajiban, tujuan, dan pengeluaran fleksibel; periksa apakah rencana tetap realistis saat ada biaya tak terduga.'::jsonb),
('d3000000-0000-4000-8000-000000000050'::uuid,'Tentukan tujuan tabungan tiga bulan dengan jumlah dan jadwal yang masuk akal. Catat asumsi dan rencana jika pemasukan berubah.'::jsonb),
('d3000000-0000-4000-8000-000000000051'::uuid,'Bandingkan dua simulasi pinjaman dengan pokok, biaya, bunga, tenor, cicilan, denda, dan total pembayaran. Jangan mengambil keputusan dari cicilan bulanan saja.'::jsonb),
('d3000000-0000-4000-8000-000000000052'::uuid,'Analisis pesan simulasi investasi/pinjaman yang menjanjikan untung pasti atau menekan untuk segera transfer. Tandai red flags dan tulis langkah aman sebelum membayar atau membagikan data.'::jsonb),
('d3000000-0000-4000-8000-000000000053'::uuid,'Susun checklist verifikasi lembaga dari kanal resmi otoritas terkait. Catat URL resmi, tanggal pengecekan, nama lembaga, dan hal yang masih belum pasti.'::jsonb),
('d3000000-0000-4000-8000-000000000054'::uuid,'Buat rencana keuangan 90 hari untuk satu tujuan nyata. Prioritaskan kebutuhan, risiko, dana yang tersedia, dan kapan harus meminta saran dari pihak tepercaya.'::jsonb),
('d3000000-0000-4000-8000-000000000055'::uuid,'Lakukan simulasi mendengar dua menit. Rangkum inti pesan, tanyakan apakah rangkuman benar, lalu baru tanyakan apakah lawan bicara ingin saran.'::jsonb),
('d3000000-0000-4000-8000-000000000056'::uuid,'Tulis tiga respons asertif: menolak ajakan berisiko, meminta waktu, dan menyampaikan kebutuhan. Pastikan tegas, sopan, dan tidak mengancam.'::jsonb),
('d3000000-0000-4000-8000-000000000057'::uuid,'Buat kesepakatan tim satu halaman yang menetapkan hasil, peran, tenggat, standar mutu, komunikasi, dan langkah saat anggota menghadapi hambatan.'::jsonb),
('d3000000-0000-4000-8000-000000000058'::uuid,'Ubah kritik umum menjadi umpan balik spesifik berisi perilaku yang terlihat, dampak, dan permintaan perubahan yang dapat dilakukan.'::jsonb),
('d3000000-0000-4000-8000-000000000059'::uuid,'Tulis refleksi setelah kegagalan simulasi: fakta, reaksi, hal yang bisa dikendalikan, pelajaran, dan satu langkah pemulihan kecil.'::jsonb),
('d3000000-0000-4000-8000-000000000060'::uuid,'Buat peta tiga orang/sumber dukungan tepercaya dan kapan menghubungi masing-masing. Untuk masalah berat atau berkepanjangan, cari bantuan orang dewasa atau profesional yang sesuai.'::jsonb),
('d3000000-0000-4000-8000-000000000061'::uuid,'Buat checklist pembukaan dan penutupan toko/ruang kerja simulasi. Sertakan langkah, standar selesai, dan apa yang harus dilaporkan jika tidak sesuai.'::jsonb),
('d3000000-0000-4000-8000-000000000062'::uuid,'Periksa dataset stok simulasi, temukan selisih, dan buat laporan dengan bukti, jumlah, kemungkinan penyebab, serta langkah eskalasi tanpa mengubah catatan secara sembarangan.'::jsonb),
('d3000000-0000-4000-8000-000000000063'::uuid,'Simulasikan tiga pelanggan: bertanya tentang produk, ragu memilih, dan membutuhkan bantuan tambahan. Latih pertanyaan terbuka dan konfirmasi kebutuhan.'::jsonb),
